using namespace std;

class Solution {
    vector<int> parent;
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
public:
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
        if (threshold == 0) {
            return vector<bool>(queries.size(), true);
        }
        for (int d = threshold + 1; d <= n; ++d) {
            for (int mult = 2 * d; mult <= n; mult += d) {
                unite(d, mult);
            }
        }
        vector<bool> ans(queries.size());
        for (size_t i = 0; i < queries.size(); ++i) {
            ans[i] = (find(queries[i][0]) == find(queries[i][1]));
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private int[] parent;
    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        parent = new int[n + 1];
        for (int i = 0; i <= n; ++i) parent[i] = i;
        if (threshold == 0) {
            List<Boolean> res = new ArrayList<>();
            for (int i = 0; i < queries.length; ++i) res.add(true);
            return res;
        }
        for (int d = threshold + 1; d <= n; ++d) {
            for (int mult = 2 * d; mult <= n; mult += d) {
                union(d, mult);
            }
        }
        List<Boolean> ans = new ArrayList<>();
        for (int[] q : queries) {
            ans.add(find(q[0]) == find(q[1]));
        }
        return ans;
    }
}

